import {highlightNext,combustionNextAction} from './combustion-guidance.js';
import {combustionProducts} from './combustion-products.js';
import {waterReactions,specimenFlames} from './combustion-observations.js';
import {mountCombustion,shelfTarget} from './combustion-workbench.js';
import {mountActivity} from './activity-ladder.js';
import {metals,nonmetals} from './model.js';
import {sampleVisual} from './specimens.js';
import {bindDrop} from './direct-manipulation.js';
import {materialCases} from './journey-cards.js';
import {bottleSolutions} from './bottle-ph-state.js';
// Keep the historical :ph evidence key for completed saved bottle observations.
export function sampleIcon(key,prefix='tray-'){return sampleVisual(key==='CO'?'C':key,false,true,prefix+key,{form:{Mg:'ribbon',Cu:'sheet',Zn:'powder',Na:'block',S:'powder',P:'powder'}[key]});}
export function mountBurn(root,c,ctx){
 const {s,has,record,notice,delay}=ctx,key=s.selected,isMetal=!!metals[key],d=isMetal?metals[key]:nonmetals[key];
 let localBurned=false,localCool=true,running=false,localPoint=null;const burned=()=>localBurned,cooled=()=>localCool;
 root.innerHTML=`<div class="combustion-studio integrated-studio" aria-label="樣本架與燃燒實驗台" id="combustion-studio" tabindex="-1"><div class="specimen-shelf"></div><div class="bench-workspace"><div class="bench-sequence"><span>取樣與燃燒</span><i>→</i><span>產物入水</span><i>→</i><span>酸鹼性比較</span></div><p class="experiment-purpose" data-stage-purpose></p><div class="burn-content"></div></div></div><div class="comparison-sheet"></div><div class="activity-mount"></div>`;
 const content=root.querySelector('.burn-content'),sheet=root.querySelector('.comparison-sheet');
 function table(){sheet.innerHTML=`<table><caption>你的觀察表 · 燃燒／加熱的產物與反應式</caption><thead><tr><th>樣本</th><th>火焰的顏色</th><th>產物與化學反應式</th><th>遇水後的產物與反應式</th><th>酸鹼性</th></tr></thead><tbody>${materialCases[c.type].map(([k,name])=>{const m=metals[k]||nonmetals[k];return `<tr><th scope="row" class="comparison-sample"><div class="comparison-sample-art">${sampleIcon(k,'record-')}</div><span>${name}</span></th><td class="flame-colour-record">${tableFlame(k)}</td><td class="combustion-product-record"><b>${combustionProducts[k].product}</b><span class="combustion-record-equation">${combustionProducts[k].equation}</span></td><td class="combustion-product-record water-product-record"><b>${["Cu","Zn"].includes(k)?"難溶於水":waterReactions[k].text}</b>${waterReactions[k].equation?`<span class="combustion-record-equation">${waterReactions[k].equation}</span>`:''}</td><td class="water-acidity-record">${has(k+(bottleSolutions[k]?':ph':':wet'))?`<b class="acidity-${bottleSolutions[k]||m.litmus}">${(bottleSolutions[k]||m.litmus)==='acid'?'酸性':m.litmus==='base'?'鹼性':'近中性（水相）'}</b><small>${(bottleSolutions[k]||m.litmus)==='acid'?'藍→紅；紅不變':m.litmus==='base'?'紅→藍；藍不變':'紅、藍皆無明顯變色'}</small>`:'尚未測試'}</td></tr>`;}).join('')}</tbody></table>`;if(c.type==='combustion'||isMetal)mountActivity(root.querySelector('.activity-mount'),ctx);}
 function renderBurn(replay=false){root.querySelector('[data-stage-purpose]').textContent='在同一台追蹤：燃燒 → 產物遇水 → 石蕊試紙觀察酸鹼性。';if(replay){localBurned=false;localCool=true;}s.tab='burn';content.innerHTML='<div data-combustion-mount></div>';mountCombustion(content.querySelector('[data-combustion-mount]'),{key,isMetal,autoLoad:!!s.autoLoad,spoonOrigin:burned()?localPoint:s.spoonOrigin,onCleanup:ctx.onCleanup,completed:burned()&&!replay,cool:cooled(),token:sampleIcon(key),name:d.name,delay,notice,onStart:()=>{running=true;},onComplete:point=>{localPoint=point;running=false;localBurned=true;record(key+':burn');if(key==='Zn')record('Zn:cool');renderBurn();table();},onCool:()=>{localPoint=[400,335];localCool=true;record('Zn:cool');renderBurn();table();},onWetComplete:()=>{record(key+(bottleSolutions[key]?':ph':':wet'));table();const completedBoard=root.querySelector('.combustion-workbench');delay(()=>{if(!completedBoard?.isConnected)return;const next=materialCases[c.type].find(([k])=>!has(k+(bottleSolutions[k]?':ph':':wet')));ctx.setCase(next?.[0]||key,false);},1400);}});s.autoLoad=false;s.spoonOrigin=null;renderShelf();const board=root.querySelector('.combustion-workbench');if(board?.dataset.combustionStage==='load'){const next=materialCases[c.type].find(([k])=>!has(k+(bottleSolutions[k]?':ph':':wet')));highlightNext(root,next?{id:'load',tool:'[data-shelf-sample="'+next[0]+'"]',label:'拿取下一個樣本'}:{id:'complete'});}}
 function renderShelf(){const shelf=root.querySelector('.specimen-shelf');shelf.hidden=false;if(c.type!=='combustion'){shelf.hidden=true;return;}shelf.innerHTML='<div class="shelf-heading"><b>鐵匠的樣本架</b><span>抓取樣本 → 放上燃燒匙</span></div>'+[['metals','金屬','metals'],['nonmetals','非金屬','nonmetals']].map(([type,title,group])=>'<section class="specimen-group '+group+'" aria-label="'+title+'樣本"><h4>'+title+'<small>'+ (group==='metals'?'銅・鎂・鋅・鈉':'硫・紅磷・碳')+'</small></h4><div class="shelf-rail">'+materialCases[type].map(([k,label])=>'<div class="shelf-specimen '+(key===k?'selected':'')+'" data-shelf-sample="'+k+'" aria-label="'+label+'樣本"><div class="specimen-vial">'+sampleIcon(k)+'</div><b>'+label+'</b><small>'+ (has(k+':burn')?'✓ 已觀察':'拖曳取用')+'</small></div>').join('')+'</div></section>').join('');for(const item of shelf.querySelectorAll('[data-shelf-sample]'))bindDrop(item,()=>shelfTarget(root.querySelector('.combustion-workbench')),{onDrop:()=>{const target=shelfTarget(root.querySelector('.combustion-workbench'));ctx.setCase(item.dataset.shelfSample,true,[Number(target.dataset.spoonX),Number(target.dataset.spoonY)]);},onMiss:()=>notice('對準眼前燃燒匙的凹槽，匙口亮起後再放開；不用回到最初的位置。')});}

 renderBurn();table();
}

function tableFlame(key){
 const label={Cu:'沒有',Mg:'白色',Zn:'藍綠色',Na:'黃色',S:'藍色',P:'黃白色',C:'沒有'}[key];
 const colour=specimenFlames[key].colour,noFlame=key==='Cu'||key==='C';
 return `<span class="flame-table-visual"><svg viewBox="0 0 64 64" aria-hidden="true"><defs><radialGradient id="table-glow-${key}"><stop stop-color="${colour}" stop-opacity=".85"/><stop offset="1" stop-color="${colour}" stop-opacity="0"/></radialGradient></defs>${noFlame?(key==='C'?'<ellipse cx="32" cy="45" rx="22" ry="12" fill="url(#table-glow-C)"/><path d="M15 47L21 37 34 40 41 34 51 49 33 54Z" fill="#343b36"/><path d="M23 43l8 6 9-5" fill="none" stroke="#e97530" stroke-width="2"/>':'<path d="M10 47L41 39 54 48 23 56Z" fill="#323c36" stroke="#8f7060"/>'):`<ellipse cx="32" cy="33" rx="30" ry="31" fill="url(#table-glow-${key})"/><path d="M16 53C3 37 27 28 28 5C46 18 34 27 47 35C57 46 47 57 32 58Z" fill="${colour}"/><path d="M24 52Q19 42 33 27Q45 44 38 54Z" fill="#fffde3"/>`}</svg><span>${label}</span></span>`;
}
